@pytest.mark.parametrize('dtype', [np.float32, np.float64, np.int32, np.int64])
@pytest.mark.parametrize('diagonal', [1, -1])
@pytest.mark.parametrize('score', [silhouette_samples, silhouette_score])
def test_silhouette_precomputed_nonzero_diagonal(dtype, diagonal, score):
    X = np.array([[0.2], [0.1], [0.12], [1.34], [1.11], [1.6]])
    distances = pairwise_distances(X).astype(dtype)
    # A single nonzero self-distance must not silently affect the scores.
    distances[2, 2] = diagonal
    original = distances.copy()
    labels = [0, 0, 0, 1, 1, 1]

    with pytest.raises(ValueError, match='non-zero elements on the diagonal'):
        score(distances, labels, metric='precomputed')
    assert_array_equal(distances, original)


